 ctx.fillStyle='#6b4a28';ctx.beginPath();ctx.ellipse(0,DEPTH,R*1.02,R*.56,0,0,Math.PI*2);ctx.fill();ctx.fillRect(-R*1.02,0,R*2.04,DEPTH);
 let disk=ctx.createLinearGradient(0,-R*.6,0,R*.6);disk.addColorStop(0,'#f6e6c0');disk.addColorStop(1,'#d9bd84');ctx.fillStyle=disk;ctx.beginPath();ctx.ellipse(0,0,R*1.02,R*.56,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8a6a3c';ctx.lineWidth=2;ctx.stroke();
