// facing preview: the hero turns toward the cursor while choosing (arrow or a nearby tile); leaving reverts
function facingFromPointer(x,y){if(!facingPick||locked||facingPick.actor!==state.hero)return null;let d=facingAt(x,y);if(d)return d;let t=pick(x+canvas.getBoundingClientRect().left,y+canvas.getBoundingClientRect().top),h=state.hero;if(!t||C.covers(h,t.x,t.y))return null;let dd=Math.abs(t.x-h.x)+Math.abs(t.y-h.y);return dd<=3?C.facing(h,t):null}
canvas.addEventListener('pointermove',e=>{if(!facingPick||pointer?.drag)return;let r=canvas.getBoundingClientRect(),d=facingFromPointer(e.clientX-r.left,e.clientY-r.top);facingPick.preview=d;state.hero.facing=d||facingPick.orig});
canvas.addEventListener('pointerleave',()=>{if(facingPick){facingPick.preview=null;state.hero.facing=facingPick.orig}});
function facingAt(x,y){for(let f of facingHits)if(Math.hypot(x-f.x,y-f.y)<=f.r)return f.dir;return null}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
