function toggleMoveLock(i){if(locked||deploying||state.outcome||!ready||state.phase!=='player')return;let d=state.deck,c=d?.movement.hand[i];if(!c||c.used)return;let L=d.moveLock||(d.moveLock=[]),at=L.indexOf(i);if(at>=0)L.splice(at,1);else{if(L.length>=2)L.shift();L.push(i)}state.selected='move';lockT=null;say(L.length?'ล็อก '+L.map(j=>D.MOVE[d.movement.hand[j].id].name).join(' + ')+' · ช่องเดินเปลี่ยนตาม':'กลับไปเลือกไพ่เดินอัตโนมัติ');window.BattleJuice?.ripple();stats()}
