function playMoveCard(i){if(locked||deploying||state.outcome||!ready)return;if(needFacing())return;if(state.deck.moveUsed===1&&!(state.deck.pendingMove&&state.deck.pendingMove.index!==i&&state.hero.mp===state.deck.pendingMove.def.move)&&!confirm('เดินครั้งที่สองจะเสียสิทธิ์ใช้ไพ่ต่อสู้ที่เหลือในเทิร์นนี้ ยืนยันหรือไม่?'))return;let r=C.playMove(state,i);if(!r.ok){say(r.reason);return}state.selected='move';say((state.deck.pendingMove?.swapped?'เปลี่ยนเป็นไพ่ ':'ไพ่ ')+r.card.name+' · กำลังเดิน '+r.card.move+(state.deck.pendingMove?.swapped?' (ยังไม่เสียครั้งการเดิน)':''));fx('text',state.hero,'#2f6f7f','+'+r.card.move+' เดิน');stats()}
