 let atk=plan.attack;if(!atk||!C.alive(atk.target)){if(plan.path.length<=1)await window.BattleCmd?.aiChoose?.(u,'wait',{});C.aiResolve(state,{...plan,attack:null});return}
 let v=V(u),end=plan.path.at(-1)||u;u.facing=C.facing(end,atk.target);let dir=screenDir(u.facing),bossSpecial=enemy&&!!plan.boss?.aoe,pose=bossSpecial?'special':atk.ranged?'cast':'strike';
 await window.BattleCmd?.aiChoose?.(u,'attack',{name:bossSpecial?C.BOSS_SKILLS[u.kind].aoe.name:atk.ranged?'ยิงระยะไกล':'โจมตี',target:atk.target,boss:bossSpecial});if(bossSpecial){skillLabel(u,C.BOSS_SKILLS[u.kind].aoe.name);cinematicUntil=performance.now()+800;await tween(420,()=>{})}if(enemy){v.pose='windup';window.BattlePolish?.swing(C.ENEMY_TYPES[u.kind]?.rank==='boss'?'hammer':u.weapon||'sword');await tween(M?.timing(u.kind,dir,'windup')?.duration||220,()=>{})}
