 if(PROJECTILE_FX.includes(kind)){let flight=kind==='bullet'?1:kind==='arrow'||kind==='stone'?1:kind==='ice'?.55:kind==='arcane'?.65:.6;await tween(playFx(kind,atk.target,{x:v.x,y:v.y,footprint:u.footprint},{color:spell?.[1]|| (u.weapon==='staff'?'#7cc5db':u.weapon==='tome'?'#f4d36a':undefined)})*flight,()=>{})}
