function pick(clientX,clientY){let r=canvas.getBoundingClientRect(),x=clientX-r.left,y=clientY-r.top,ordered=state.map.tiles.filter(t=>!t.void).sort((a,b)=>depth(b.x,b.y)-depth(a.x,a.y));for(let t of ordered){if((state.map.authoredTerrain||state.map.hillArt)&&window.TacticsHillArt){let g=TacticsHillArt.geometry(state.map,t,point,depth);if(TacticsSurface.contains(g.p,x,y))return t;if(g.faces.some(f=>TacticsSurface.contains(f,x,y)))return null;}else{let p=point(t.x,t.y,t.h);if(Math.abs(x-p.x)/(camera.w/2)+Math.abs(y-p.y)/(camera.h/2)<=1)return t}}return null}
function inspect(t){hover=t;previewPathTo(t);if(typeof sel()==='number'&&targetsEnemy()&&t){let hu=C.unitAt(state,t.x,t.y);if(hu?.side==='enemy'&&C.alive(hu)&&!C.combatReason(state,sel(),hu))lockT=hu.id}if(!t){$('tileInspector').textContent='ชี้ช่องเพื่อดูความสูงและค่าเดิน';return}let u=C.unitAt(state,t.x,t.y)||state.units.find(u=>!u.removed&&u.hp<=0&&C.covers(u,t.x,t.y)),cost=reach.costs.get(C.key(t.x,t.y));$('tileInspector').textContent=u?`${u.name} · HP ${u.hp}/${u.maxHp}${u.element?' · ธาตุ'+(C.ELEMENT_NAMES?.[u.element]||''):''}${(u.traits||[]).length?' · '+u.traits.map(k=>C.TRAITS[k]).join(', '):''} · ยืนบน${(C.TERRAIN?.[t.kind]||{}).name||''}`+(u.side==='enemy'&&typeof sel()==='number'?' · '+(C.combatReason(state,sel(),u)||'โจมตีได้'):''):(pathPreview?.dest===C.key(t.x,t.y)?`เดิน ${pathPreview.steps} ช่อง · ใช้กำลังเดิน ${pathPreview.cost} · `:'')+`ช่อง ${t.x+1},${t.y+1} · สูง ${t.h} · ${(C.TERRAIN?.[t.kind]||{}).name||''}${(C.TERRAIN?.[t.kind]||{}).note?' ('+C.TERRAIN[t.kind].note+')':''} · ${t.blocked?'สิ่งกีดขวาง':cost===undefined?'เดินไม่ถึง':'ค่าเดิน '+cost}`;if(u?.hp>0&&Object.keys(u.statuses||{}).length)$('tileInspector').textContent+=' · '+Object.entries(u.statuses).map(([k,v])=>C.STATUS[k].name+' '+v.turns+' CT').join(' / ');if(u&&u.hp<=0){$('tileInspector').textContent=u.name+' · สลบ · เหลือ '+u.downTurns+' CT'+(u.side==='ally'?' · ยืนติดแล้วคลิกเพื่อช่วยฟื้น (แรง 15 / คำสั่งต่อสู้ 1)':'')}if(u&&u.hp>0&&u.side==='enemy'){if(typeof sel()==='number'){let pv=C.previewCard(state,sel(),u);if(pv)$('tileInspector').textContent+=' · HP '+u.hp+'→'+pv.hpAfter+' · โดน '+pv.hit+'% · คริ '+pv.crit+'% · '+pv.angle}stats()}}
function reset(randomize=false){if(locked)return;stopUntil=slowUntil=slowStart=0;resultShown=false;$('v27Facing')?.remove();document.querySelectorAll('#resultOverlay .v27-reward').forEach(e=>e.remove());pending=null;if(randomize)$('seed').value='FIELD-'+Math.floor(Math.random()*999999);let seed=$('seed').value.trim()||'FOREST-04',theme=$('theme').value,h=state.leader||state.hero;
 let cfg=B?.battleConfig?.()||{};if(cfg.theme)theme=cfg.theme;state=C.create(seed,theme,cfg.mode||$('fieldMode').value,{weapon:h.weapon,shield:h.shield,deck:B?.deckConfig?.(),decks:B?.unitDecks?.(),allies:cfg.allies,encounter:cfg.encounter});$('tacticsLayer').classList.toggle('expedition',!!cfg.encounter);B?.prepare(state);window.MonsterArt?.reset();window.MonsterArt?.preload(state.units);vis={};cursor={x:state.hero.x,y:state.hero.y};hover=null;effects=[];messages=[];pan={x:0,y:0};window.BattleDiagnostics?.reset();zoom=$('tacticsLayer').classList.contains('fullbattle')?1.85:1;$('resultOverlay').hidden=true;
 document.querySelector('#tacticsLayer .title h1').textContent=state.encounter?'ออกสำรวจ · '+state.encounter.name:(state.map.mode==='battle'?'สนามรบทดสอบ · ':'')+(theme==='modular-wilds'?'ป่าผสม · สุ่มชิ้นส่วน':theme==='terraced-hill'?'เนินหินลานขั้นบันได':theme==='forest'?'ลานฝึกริมป่า':'เหมืองหินร้าง');say('สนาม '+seed+' พร้อม · คริสตัล 3 เม็ดต่อเทิร์น · คลิกช่องเพื่อเดิน · คลิกศัตรูเพื่อโจมตี');selectMoveMode();size();locked=true;stats();clearTimeout(introTimer);introTimer=setTimeout(()=>{locked=false;startDeploy()},60)}
canvas.addEventListener('pointerdown',e=>{pointer={id:e.pointerId,x:e.clientX,y:e.clientY,pan:{...pan},drag:false};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(pointer&&pointer.id===e.pointerId){let dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(dx,dy)>6)pointer.drag=true;if(pointer.drag){pan={x:pointer.pan.x+dx,y:pointer.pan.y+dy};size();return}}inspect(pick(e.clientX,e.clientY))});
canvas.addEventListener('pointerup',e=>{if(pointer?.id!==e.pointerId)return;let dragged=pointer.drag;pointer=null;if(!dragged&&deploying){deployClick(pick(e.clientX,e.clientY));return}if(!dragged){let rr=canvas.getBoundingClientRect(),fd=facingAt(e.clientX-rr.left,e.clientY-rr.top);if(!fd&&facingPick&&!locked)fd=facingFromPointer(e.clientX-rr.left,e.clientY-rr.top);if(fd&&facingPick&&!locked){state.hero.facing=fd;facingPick=null;window.BattlePolish?.sound('block',.2);stats();if(facingEnd)endTurn();return}let t=pick(e.clientX,e.clientY);if(t){cursor={x:t.x,y:t.y};confirmAct(t)}}});
canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('pointerleave',()=>{if(!pointer)inspect(null)});
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.6,Math.min(2.4,zoom-e.deltaY*.001));size()},{passive:false});
document.addEventListener('keydown',e=>{if(B&&!B.visible())return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('help').open)return;let k=e.key.toLowerCase();if((e.key==='Enter'||k===' ')&&e.target.closest?.('button,summary,a,[contenteditable=true]'))return;
 if(k>='1'&&k<='6'){selectCombat(Number(k)-1);e.preventDefault()}else if(MOVE_KEYS.includes(k)){toggleMoveLock(MOVE_KEYS.indexOf(k));e.preventDefault()}
 if(e.key==='Escape'&&typeof sel()==='number'){selectMoveMode();e.preventDefault();e.stopImmediatePropagation()}if(k==='a')toggleAnchorEditor();if(e.key==='[')turnView(-1);if(e.key===']')turnView(1);if(k==='h'){toggleSeeThrough();e.preventDefault()}if(k===' '&&!locked){endTurn();e.preventDefault()}
 if(e.key.startsWith('Arrow')){let dl={ArrowRight:[1,0],ArrowLeft:[-1,0],ArrowDown:[0,1],ArrowUp:[0,-1]}[e.key];cursor.x=Math.max(0,Math.min((state.map.width||state.map.size)-1,cursor.x+dl[0]));cursor.y=Math.max(0,Math.min((state.map.height||state.map.size)-1,cursor.y+dl[1]));inspect(C.at(state.map,cursor.x,cursor.y));e.preventDefault()}
 if(k==='f'&&e.target===canvas){confirmAct(C.at(state.map,cursor.x,cursor.y));e.preventDefault()}if(e.key==='Enter'&&e.target===canvas){endTurn();e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('keydown',e=>{if(e.key!=='Enter'||B&&!B.visible()||locked||e.target.closest?.('input,textarea,select,button,dialog'))return;let u=lockUnit();if(u){e.preventDefault();e.stopImmediatePropagation();act(C.at(state.map,u.x,u.y))}},true);
