function anchorPanel(){let f=A.directions[anchorEdit.dir][anchorEdit.pose];$('anchorEditor').innerHTML=`<div class="ae-row"><label>ทิศ <select id="aeDir">${Object.keys(A.directions).map(d=>`<option ${d===anchorEdit.dir?'selected':''}>${d}</option>`).join('')}</select></label><label>ท่า <select id="aePose">${POSES.filter(p=>A.directions[anchorEdit.dir][p]).map(p=>`<option ${p===anchorEdit.pose?'selected':''}>${p}</option>`).join('')}</select></label></div>
 <label>มุมอาวุธ <input id="aeRot" type="range" min="-180" max="180" value="${f.rotation}"> <b id="aeRotV">${f.rotation}°</b></label>
 <div class="ae-row"><label><input type="checkbox" id="aeRB" ${f.rightBehind?'checked':''}> อาวุธอยู่หลังตัว</label><label><input type="checkbox" id="aeLB" ${f.leftBehind?'checked':''}> โล่อยู่หลังตัว</label></div>
 <small>ลากจุด<b style="color:#e64731">แดง</b> = มือหลัก (อาวุธ) · <b style="color:#3376d5">น้ำเงิน</b> = มือรอง (โล่) · ลองเปลี่ยนอาวุธ/โล่ด้านบน</small>
 <div class="ae-row"><button id="aeSave">บันทึก</button><button id="aeReset">คืนค่าท่านี้</button><button id="aeExport">ส่งออก tactics-sprites.js</button></div><small id="aeStatus"></small>`;
 $('aeDir').onchange=e=>{anchorEdit.dir=e.target.value;state.hero.facing=anchorEdit.dir;anchorPanel()};$('aePose').onchange=e=>{anchorEdit.pose=e.target.value;anchorPanel()};
 $('aeRot').oninput=e=>{f.rotation=+e.target.value;$('aeRotV').textContent=f.rotation+'°'};$('aeRB').onchange=e=>f.rightBehind=e.target.checked;$('aeLB').onchange=e=>f.leftBehind=e.target.checked;
 $('aeSave').onclick=saveAnchors;$('aeReset').onclick=()=>{try{let o=JSON.parse(localStorage.getItem(ANCHOR_KEY)||'{}');delete o[anchorEdit.dir]?.[anchorEdit.pose];localStorage.setItem(ANCHOR_KEY,JSON.stringify(o))}catch(e){}$('aeStatus').textContent='คืนค่าแล้ว — รีเฟรชหน้าเพื่อโหลดค่าเดิม'};
 $('aeExport').onclick=()=>{let txt='/* Generated weaponless character art; runtime attaches equipment at normalized hand anchors. Hand points edited in developer mode. */\nconst TACTICS_SPRITES = '+JSON.stringify(A,null,2)+';\n',u=URL.createObjectURL(new Blob([txt],{type:'text/javascript'})),a=document.createElement('a');a.href=u;a.download='tactics-sprites.js';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}}
function saveAnchors(){try{let o=JSON.parse(localStorage.getItem(ANCHOR_KEY)||'{}'),f=A.directions[anchorEdit.dir][anchorEdit.pose];o[anchorEdit.dir]=o[anchorEdit.dir]||{};o[anchorEdit.dir][anchorEdit.pose]={right:f.right.map(n=>+n.toFixed(4)),left:f.left.map(n=>+n.toFixed(4)),rotation:f.rotation,rightBehind:!!f.rightBehind,leftBehind:!!f.leftBehind};localStorage.setItem(ANCHOR_KEY,JSON.stringify(o));$('aeStatus').textContent='✓ บันทึก '+anchorEdit.dir+' / '+anchorEdit.pose+' ในเบราว์เซอร์นี้'}catch(e){$('aeStatus').textContent='บันทึกไม่ได้'}}
function toggleAnchorEditor(){let ed=$('anchorEditor'),fw=document.querySelector('#tacticsLayer .field-wrap');if(ed.parentElement!==fw)fw.appendChild(ed);anchorEdit.open=!anchorEdit.open;$('anchorEditor').hidden=!anchorEdit.open;$('anchorToggle').classList.toggle('selected',anchorEdit.open);if(anchorEdit.open){anchorEdit.dir=state.hero.facing;zoom=2.1;let p0=ground(V(state.hero)),r=canvas.getBoundingClientRect();pan={x:pan.x+(r.width/2-p0.x),y:pan.y+(r.height*.62-p0.y)};size();let p1=ground(V(state.hero));pan.x+=r.width/2-p1.x;pan.y+=r.height*.62-p1.y;size();anchorPanel()}else{zoom=1;pan={x:0,y:0};size()}}
canvas.addEventListener('pointerdown',e=>{if(!anchorEdit.open||!heroGeom)return;let r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,g=heroGeom;for(let n of ['right','left']){let px=g.bodyLeft+g.frame[n][0]*g.bodySize,py=g.bodyTop+g.frame[n][1]*g.bodySize;if(Math.hypot(x-px,y-py)<14){anchorEdit.drag={n,id:e.pointerId};e.stopImmediatePropagation();canvas.setPointerCapture(e.pointerId);return}}},true);
canvas.addEventListener('pointermove',e=>{let d=anchorEdit.drag;if(!d||e.pointerId!==d.id)return;let r=canvas.getBoundingClientRect(),g=heroGeom,f=A.directions[anchorEdit.dir][anchorEdit.pose];f[d.n]=[Math.max(0,Math.min(1,(e.clientX-r.left-g.bodyLeft)/g.bodySize)),Math.max(0,Math.min(1,(e.clientY-r.top-g.bodyTop)/g.bodySize))];e.stopImmediatePropagation()},true);
canvas.addEventListener('pointerup',e=>{if(anchorEdit.drag&&e.pointerId===anchorEdit.drag.id){anchorEdit.drag=null;saveAnchors();e.stopImmediatePropagation()}},true);
$('anchorToggle').onclick=toggleAnchorEditor;
async function turnView(d){if(locked)return;locked=true;pending=null;stats();let from=rot,setRot=n=>{n=((n%4)+4)%4;if(n===rot)return;rot=n;window.BattleArt?.setView(rot);$('rotLabel').textContent=['N','E','S','W'][rot]};try{await tween(640,k=>{let e=k<.5?4*k*k*k:1-Math.pow(-2*k+2,3)/2;viewAngle=from+d*e;setRot(Math.round(viewAngle))});viewAngle=((from+d)%4+4)%4;setRot(viewAngle);rot=viewAngle;size()}finally{viewAngle=rot;locked=false;stats()}}
$('rotLeft').onclick=()=>turnView(-1);$('rotRight').onclick=()=>turnView(1);
function fxLab(){let el=$('fxLab'),fw=document.querySelector('#tacticsLayer .field-wrap');if(el.parentElement!==fw)fw.appendChild(el);el.hidden=!el.hidden;$('fxToggle').classList.toggle('selected',!el.hidden);
 el.innerHTML='<b>ทดสอบเอฟเฟกต์</b><small>เล่นจากตัวเราไปศัตรูที่ใกล้ที่สุด</small><div class="fx-grid">'+Object.entries(FX_LABELS).map(([k,n])=>`<button data-fx="${k}">${n}</button>`).join('')+'</div><label><input type="checkbox" id="fxBig"> แรง ×1.45 (ท่าหนัก)</label>';
 el.querySelectorAll('[data-fx]').forEach(b=>b.onclick=()=>{let h=state.hero,f=C.living(state,'enemy').sort((a,c)=>C.dist(a,h)-C.dist(c,h))[0]||{x:h.x+2,y:h.y},k=b.dataset.fx,self=['heal','buff','shield','parry'].includes(k);playFx(k,self?h:f,self?f:h,{scale:$('fxBig').checked?1.45:1})})}
$('fxToggle').onclick=fxLab;
window.TacticsLab={lockTarget:()=>lockUnit(),hoverOut:()=>{let hu=hover&&C.unitAt(state,hover.x,hover.y);return hu&&hu.side==='enemy'&&C.alive(hu)&&typeof sel()==='number'&&targetsEnemy()&&C.combatReason(state,sel(),hu)?hu:null},headY,isDeploying:()=>deploying,fxText:(u,c,x)=>fx('text',u,c,x),pathPreview:()=>pathPreview,unitPoint:u=>ground(V(u)),camera:()=>camera,canvas,facingPending:()=>!!facingPick,pace:PACE,chooseFacing,projectTile:(x,y)=>point(x,y,C.at(state.map,x,y)?.h||0),hover:()=>hover,selected:()=>sel(),focusUnit,runQueue,reset,size,stats,say,finish:finishCheck,getState:()=>state,presentRituals,copyRewardCard,setLoadout(w,sh){state.hero.weapon=w;state.hero.shield=!!sh;$('weapon').value=w;$('shield').checked=!!sh;stats()},isLocked:()=>locked,playFx,freeze:f=>{frozen=f},endTurn,playMoveCard,selectCombat,act,runCombat};
